package com.puzzlang.runtime;

/**
 * AocRuntime — dynamic dispatch for all runtime operations.
 *
 * All methods take Object and return Object so they work with
 * INVOKESTATIC from our generated bytecode.
 *
 * NEW: range construction + range method dispatch.
 */
public class PuzzRuntime {

    // ── Range construction ────────────────────────────────────────────────────

    /** Called for  start..end  (exclusive) */
    public static Object makeRange(Object start, Object end) {
        return new PuzzRange(toInt(start), toInt(end), false);
    }

    /** Called for  start..=end  (inclusive) */
    public static Object makeRangeInclusive(Object start, Object end) {
        return new PuzzRange(toInt(start), toInt(end), true);
    }

    // ── Range method dispatch ─────────────────────────────────────────────────

    /**
     * Dispatches  receiver.method(args)  calls.
     *
     * For AocRange receivers this handles all built-in methods.
     * In a future version, this would use invokedynamic for efficiency.
     */
    public static Object callMethod(Object receiver, String method, Object... args) {
        if (receiver instanceof PuzzRange range) {
            return switch (method) {
                case "sum"         -> range.sum();
                case "product"     -> range.product();
                case "count"       -> (long) range.count();
                case "min"         -> range.min();
                case "max"         -> range.max();
                case "isEmpty"     -> range.isEmpty();
                case "isInclusive" -> range.inclusive();
                case "start"       -> range.startValue();
                case "end"         -> range.lastValue();
                case "contains"    -> range.contains(toInt(args[0]));
                case "overlaps"    -> {
                    if (!(args[0] instanceof PuzzRange other))
                        throw new RuntimeException("overlaps() requires a range argument");
                    yield range.overlaps(other);
                }
                case "intersection" -> {
                    if (!(args[0] instanceof PuzzRange other))
                        throw new RuntimeException("intersection() requires a range argument");
                    PuzzRange result = range.intersection(other);
                    yield result != null ? result : "null";
                }
                case "step"        -> range.step(toInt(args[0]));
                case "toList"      -> {
                    var list = new java.util.ArrayList<Integer>();
                    range.forEach(list::add);
                    yield list;
                }
                default -> throw new RuntimeException(
                        "PuzzLang: range has no method '" + method + "'"
                );
            };
        }

        if (receiver instanceof PuzzRange.SteppedRange sr) {
            return switch (method) {
                case "sum"   -> sr.sum();
                case "count" -> (long) sr.count();
                default -> throw new RuntimeException(
                        "PuzzLang: stepped range has no method '" + method + "'"
                );
            };
        }

        throw new RuntimeException(
                "PuzzLang: cannot call method '" + method + "' on " +
                        (receiver == null ? "null" : receiver.getClass().getSimpleName())
        );
    }

    // ── Iteration ─────────────────────────────────────────────────────────────

    /**
     * Returns the java.lang.Iterable for a value — used by for-in loops.
     */
    @SuppressWarnings("unchecked")
    public static Iterable<Object> toIterable(Object val) {
        if (val instanceof PuzzRange r)             return (Iterable<Object>)(Iterable<?>) r;
        if (val instanceof PuzzRange.SteppedRange s) return (Iterable<Object>)(Iterable<?>) s;
        if (val instanceof Iterable<?> it)          return (Iterable<Object>) it;
        throw new RuntimeException(
                "PuzzLang: '" + val + "' is not iterable"
        );
    }

    // ── Arithmetic ────────────────────────────────────────────────────────────

    public static Object add(Object a, Object b) {
        if (a instanceof Integer ia && b instanceof Integer ib) return ia + ib;
        return String.valueOf(a) + String.valueOf(b);
    }

    public static Object sub(Object a, Object b) { return toInt(a) - toInt(b); }
    public static Object mul(Object a, Object b) { return toInt(a) * toInt(b); }
    public static Object div(Object a, Object b) {
        int d = toInt(b);
        if (d == 0) throw new ArithmeticException("PuzzLang: division by zero");
        return toInt(a) / d;
    }

    // ── Comparisons ───────────────────────────────────────────────────────────

    public static Object eq(Object a, Object b) {
        if (a == null) return b == null;
        return a.equals(b);
    }
    public static Object neq(Object a, Object b) { return !(Boolean) eq(a, b); }
    public static Object lt(Object a, Object b)  { return toInt(a) <  toInt(b); }
    public static Object lte(Object a, Object b) { return toInt(a) <= toInt(b); }
    public static Object gt(Object a, Object b)  { return toInt(a) >  toInt(b); }
    public static Object gte(Object a, Object b) { return toInt(a) >= toInt(b); }

    // ── Truth testing ─────────────────────────────────────────────────────────

    public static boolean isTruthy(Object val) {
        if (val == null)              return false;
        if (val instanceof Boolean b)  return b;
        if (val instanceof Integer i)  return i != 0;
        if (val instanceof Long l)     return l != 0;
        if (val instanceof String s)   return !s.isEmpty();
        return true;
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    public static int toInt(Object val) {
        if (val instanceof Integer i) return i;
        if (val instanceof Long l)    return l.intValue();
        if (val instanceof String s)  {
            try { return Integer.parseInt(s.trim()); }
            catch (NumberFormatException e) {
                throw new RuntimeException("PuzzLang: cannot convert '" + s + "' to int");
            }
        }
        throw new RuntimeException(
                "PuzzLang: expected int, got " +
                        (val == null ? "null" : val.getClass().getSimpleName())
        );
    }
}